  add({"id":"fed-hr915","level":"federal","bill":"H.R. 915","title":"Small Business Technological Advancement Act","session":"119th Congress","stage":"one-chamber","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/915"},"status":"Introduced February 4, 2025. Committee: Small Business and Entrepreneurship; Small Business","summary":"This bill authorizes the Small Business Administration (SBA) to finance under the 7(a) loan program business software or cloud computing services that facilitate business operations, product or service delivery, payroll processing, human resources functions, sales and billing functions, or accounting or tracking of inventory. Such software or services include business tools that utilize artificial intelligence. The 7(a) loan program is the SBA's…","lastAction":{"date":"2026-07-13","text":"Received in the Senate and Read twice and referred to the Committee on Small Business and Entrepreneurship."},"subjects":["Advanced technology and technological innovations","Computer security and identity theft","Government lending and loan guarantees"],"passing":true});
  add({"id":"fed-hr993","level":"federal","bill":"H.R. 993","title":"Emerging Innovative Border Technologies Act","session":"119th Congress","stage":"one-chamber","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/993"},"status":"Introduced February 5, 2025. Committee: Homeland Security and Governmental Affairs; Homeland Security","summary":"This bill requires U.S. Customs and Border Protection (CBP) and the Science and Technology Directorate of the Department of Homeland Security to develop a plan to identify, integrate, and deploy emerging and innovative technologies to improve border security operations. Such technologies may incorporate artificial intelligence, machine-learning, automation, fiber-optic sensing technology, nanotechnology, optical and cognitive radar, modeling and…","lastAction":{"date":"2025-03-11","text":"Received in the Senate and Read twice and referred to the Committee on Homeland Security and Governmental Affairs."},"subjects":["Advanced technology and technological innovations","Border security and unlawful immigration","Computers and information technology","Congressional oversight","Homeland security","Law enforcement administration and funding","Performance measurement","Right of privacy","Technology assessment"],"passing":true});
