  add({"id":"fed-hr1121","level":"federal","bill":"H.R. 1121","title":"No DeepSeek on Government Devices Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/1121"},"status":"Introduced February 7, 2025. Committee: Oversight and Government Reform","summary":"This bill directs the Office of Management and Budget to develop standards and guidance requiring removal of the DeepSeek application from federal agency information technology. Such standards and guidance also apply to any successor application developed or provided by High Flyer or entities owned by High Flyer. DeepSeek is an artificial intelligence start-up founded in 2023 and based in Hangzhou, China. DeepSeek's chief executive officer also…","lastAction":{"date":"2025-02-07","text":"Referred to the House Committee on Oversight and Government Reform."},"subjects":["Computer security and identity theft","Computers and information technology","Executive agency funding and structure","Internet, web applications, social media"],"passing":true});
