  add({"id":"fed-hr1350","level":"federal","bill":"H.R. 1350","title":"DOE and NSF Interagency Research Act","session":"119th Congress","stage":"one-chamber","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/1350"},"status":"Introduced February 13, 2025. Committee: Commerce, Science, and Transportation; Science, Space, and Technology","summary":"DOE and NSF Interagency Research Act This bill provides statutory authority for a research and development partnership between the Department of Energy (DOE) and the National Science Foundation (NSF). Specifically, the bill requires DOE and NSF to enter into a memorandum of understanding to support cross-cutting and collaborative research and development that furthers the missions of both agencies. Through the partnership, DOE and NSF may…","lastAction":{"date":"2025-03-25","text":"Received in the Senate and Read twice and referred to the Committee on Commerce, Science, and Transportation."},"subjects":["Advanced technology and technological innovations","Biological and life sciences","Computers and information technology","Congressional oversight","Department of Energy","Earth sciences","Intergovernmental relations","National Science Foundation","Research and development"],"passing":true});
  add({"id":"fed-hr1615","level":"federal","bill":"H.R. 1615; S. 753","title":"Strengthening Exports Against China Act","session":"119th Congress","stage":"committee","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/1615"},"status":"Introduced in the House February 26, 2025 and in the Senate February 26, 2025. Committees: House: Financial Services. Senate: Banking, Housing, and Urban Affairs","summary":"This bill allows the Export-Import Bank of the United States (EXIM) to exclude financing provided to certain U.S. exporters from its default rate cap calculations. EXIM, the official export credit agency of the United States, provides financing for U.S. exports of goods and services. EXIM monitors credit and other transaction risks, reserves against losses, and submits quarterly reports to Congress on its default rate. If its default rate…","lastAction":{"date":"2026-03-26","text":"Committee on Banking, Housing, and Urban Affairs. Hearings held."},"subjects":["Asia","China","Competitiveness, trade promotion, trade deficits","Government lending and loan guarantees","Interest, dividends, interest rates"],"passing":true});
