  add({"id":"fed-hr1736","level":"federal","bill":"H.R. 1736","title":"Generative AI Terrorism Risk Assessment Act","session":"119th Congress","stage":"one-chamber","source":{"label":"Congress.gov","url":"https://www.congress.gov/bill/119th-congress/house-bill/1736"},"status":"Introduced February 27, 2025. Committee: Homeland Security and Governmental Affairs; Homeland Security","summary":"This bill requires the Department of Homeland Security (DHS) to periodically provide Congress with an assessment of threats to the United States posed by the use of generative artificial intelligence (AI) for terrorism. Generative AI is defined as the class of AI models that emulate the structure and characteristics of input data to generate derived synthetic content, including images, videos, audio, text, and other digital content. The bill…","lastAction":{"date":"2025-11-20","text":"Received in the Senate and Read twice and referred to the Committee on Homeland Security and Governmental Affairs."},"subjects":["Advanced technology and technological innovations","Congressional oversight","Government information and archives","Terrorism"]});
