  S("CA","AB 102",4,"enacted","2025-06-27","Chaptered by Secretary of State - Chapter 5, Statutes of 2025.","Budget Act of 2025.","The Budget Act of 2025 would make appropriations for the support of state government for the 2025–26 fiscal year. This bill would amend the Budget Act of 2025 by amending, adding, and repealing items of appropriation and making other changes. This bill would declare that it is to take effect immediately as a Budget Bill.",[],"http://leginfo.legislature.ca.gov/faces/billNavClient.xhtml?bill_id=202520260AB102",1,1);
  S("CA","AB 103",4,"one-chamber","2025-07-02","Re-referred to Com. on B. & F. R.","Budget Acts of 2022, 2023, and 2024.","The Budget Act of 2022, the Budget Act of 2023, and the Budget Act of 2024 made appropriations for the support of state government for the 2022–23, 2023–24, and 2024–25 fiscal years, respectively. This bill would amend those budget acts by amending, adding, and repealing items of appropriation and making other changes. This bill would declare that it is to take effect immediately as a Budget Bill.",[],"http://leginfo.legislature.ca.gov/faces/billNavClient.xhtml?bill_id=202520260AB103",1,1);
