  S("TN","SB 1700",53,"enacted","2026-05-27","Pub. Ch. 1082","Consumer Protection - As enacted, requires the Tennessee advisory commission on intergovernmental relations (TACIR) to conduct a study of the potential regulation of artificial intelligence systems and generative artificial intelligence chatbots in this state. - Amends TCA Title 29; Title 37 and Title 47.","",[],"https://wapp.capitol.tn.gov/apps/BillInfo/Default?BillNumber=SB1700&ga=114",1,0);
